  firstName: string;
  lastName: string;
  email: string;
  company: string;
  jobTitle: string | null;
  companySize: string | null;
  timeline: string | null;
  useCase: string | null;
  additionalNotes: string | null;
  status: string;
  ownerNotified: boolean;
  createdAt: string;
  updatedAt: string;
}

export async function createDemoRequest(data: {
  firstName: string;
  lastName: string;
  email: string;
  company: string;
  jobTitle?: string;
  companySize?: string;
  timeline?: string;
  useCase?: string;
  additionalNotes?: string;
}): Promise<DemoRequest> {
  // Use Supabase to insert the demo request
  const { supabase } = await import('./supabase');

  const { data: result, error } = await supabase
    .from('demo_requests')
    .insert({
      first_name: data.firstName,
      last_name: data.lastName,
      email: data.email,
      company: data.company,
      job_title: data.jobTitle || null,
      company_size: data.companySize || null,
      timeline: data.timeline || null,
      use_case: data.useCase || null,
      additional_notes: data.additionalNotes || null,
      status: 'new',
      owner_notified: false,
    })
    .select()
    .single();

  if (error) {
    generalLog.error('Failed to create demo request:', error);
    throw new Error('Failed to submit demo request');
  }

  return {
    id: result.id,
    firstName: result.first_name,
    lastName: result.last_name,
    email: result.email,
    company: result.company,
    jobTitle: result.job_title,
    companySize: result.company_size,
    timeline: result.timeline,
    useCase: result.use_case,
    additionalNotes: result.additional_notes,
    status: result.status,
    ownerNotified: result.owner_notified,
    createdAt: result.created_at,
    updatedAt: result.updated_at,
  };
}

export async function getDemoRequests(limit: number = 50): Promise<DemoRequest[]> {
  const { supabase } = await import('./supabase');

  const { data, error } = await supabase
    .from('demo_requests')
    .select('*')
    .order('created_at', { ascending: false })
    .limit(limit);

  if (error) {
    generalLog.error('Failed to get demo requests:', error);
    return [];
  }

  return data.map((r: any) => ({
    id: r.id,
    firstName: r.first_name,
    lastName: r.last_name,
    email: r.email,
    company: r.company,
    jobTitle: r.job_title,
    companySize: r.company_size,
    timeline: r.timeline,
    useCase: r.use_case,
    additionalNotes: r.additional_notes,
    status: r.status,
    ownerNotified: r.owner_notified,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  }));
}


// ============ Pilot Requests ============

export interface PilotRequest {
  id: number;
  name: string;
  email: string;
  company: string | null;
  role: string | null;
  systemUrl: string | null;
  description: string | null;
  source: 'website' | 'cli' | 'github' | 'referral' | 'other';
  status: 'new' | 'contacted' | 'scanning' | 'report_sent' | 'pilot_active' | 'converted' | 'declined';
  scanResult: unknown | null;
  reportUrl: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
  contactedAt: string | null;
}

export async function createPilotRequest(data: {
  name: string;
  email: string;
  company?: string;
  role?: string;
  systemUrl?: string;
  description?: string;
  source?: 'website' | 'cli' | 'github' | 'referral' | 'other';
}): Promise<{ id: number }> {
  const { supabase } = await import('./supabase');

  const { data: result, error } = await supabase
    .from('pilot_requests')
    .insert({
      name: data.name,
      email: data.email,
      company: data.company || null,
      role: data.role || null,
      system_url: data.systemUrl || null,
      description: data.description || null,
      source: data.source || 'website',
      status: 'new',
    })
    .select('id')
    .single();

  if (error) {
    generalLog.error('Failed to create pilot request:', error);
    throw new Error('Failed to submit pilot request');
  }

  return { id: result.id };
}

export async function getPilotRequestById(id: number): Promise<PilotRequest | null> {
  const { supabase } = await import('./supabase');

  const { data, error } = await supabase
    .from('pilot_requests')
    .select('*')
    .eq('id', id)
    .single();

  if (error) {
    generalLog.error('Failed to get pilot request by id:', error);
    return null;
  }

  return data as PilotRequest;
}

export async function getPilotRequests(limit: number = 50): Promise<PilotRequest[]> {
  const { supabase } = await import('./supabase');

  const { data, error } = await supabase
    .from('pilot_requests')
    .select('*')
    .order('createdAt', { ascending: false })
    .limit(limit);

  if (error) {
    generalLog.error('Failed to get pilot requests:', error);
    return [];
  }

  return data as PilotRequest[];
}

export async function updatePilotRequestStatus(
  id: number,
  status: 'new' | 'contacted' | 'scanning' | 'report_sent' | 'pilot_active' | 'converted' | 'declined',
  notes?: string
): Promise<void> {
  const { supabase } = await import('./supabase');

  const updates: Record<string, unknown> = { status };
  if (notes !== undefined) {
    updates.notes = notes;
  }
  if (status === 'contacted') {
    updates.contactedAt = new Date().toISOString();
  }

  const { error } = await supabase
    .from('pilot_requests')
    .update(updates)
    .eq('id', id);

  if (error) {
    generalLog.error('Failed to update pilot request:', error);
    throw new Error('Failed to update pilot request');
  }
}


// ============ Gravito Stats Functions ============

export async function getGravitoStats(userId: number, days: number = 30): Promise<{
  total: number;
  passed: number;
  blocked: number;
  warned: number;
  proofsGenerated: number;
  artifactsReviewed: number;
