/**
 * User & Auth Query Module
 * 
 * Re-exports user, API key, and subscription functions from the monolith db.ts.
 */
export {
  // User functions
  getUserByOpenId,
  upsertUser,
  getUserById,
  getUserByEmail,

  // API Key functions
  createApiKey,
  getApiKeysByUserId,
  validateApiKey,
  deleteApiKey,
  regenerateApiKey,

